/**
 * test-sleap-tracker.mjs — pose/sleap-tracker.js, the port of sleap-nn's tracker,
 * against UPSTREAM sleap-nn.
 *
 * The fixture (tests/fixtures/sleap-tracker/reference.json, regenerated by
 * make_fixture.py there) is 900 frames of synthetic detections — four animals
 * passing close to each other, missed detections, missing nodes, spurious poses,
 * empty frames — tracked by sleap-nn's own `run_tracker` under six configs that
 * cover both candidate methods, all four scorers, the three reductions, both
 * matchers, the track cap, pre- and post-culling and connect-single-breaks.
 * Every track id must agree. (The port was also checked on 9 full proofread SLAP
 * videos and 9 option combinations, ~520,000 detections, all identical.)
 *
 * Ties are where a port silently drifts, so the three pieces that decide them
 * are pinned on their own: SciPy's `linear_sum_assignment` (optimal cost vs
 * brute force, plus SciPy's own answers on constant and tied matrices), numpy's
 * unstable `argsort` (greedy matching, NMS) and CPython's set iteration order,
 * which fixes `fixed_window`'s column order (taken from CPython 3.11, sleap-nn's
 * interpreter). The argsort answers were checked on 406 tie-heavy arrays.
 *
 * Run:  node tests/test-sleap-tracker.mjs
 */
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const HERE = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.resolve(HERE, '..');
const ST = await import(pathToFileURL(path.join(ROOT, 'pose', 'sleap-tracker.js')).href);

let passed = 0, failed = 0; const failures = [];
function ok(c, m) { if (c) passed++; else { failed++; failures.push(m); console.error('  ✗ ' + m); } }
function eq(a, e, m) { ok(a === e, `${m} (expected ${e}, got ${a})`); }
function group(n) { console.log('\n• ' + n); }

// sleap-nn's keyword arguments -> the port's config keys
const KW = {
    window_size: 'windowSize', min_new_track_points: 'minNewTrackPoints', candidates_method: 'candidatesMethod',
    min_match_points: 'minMatchPoints', features: 'features', scoring_method: 'scoringMethod',
    scoring_reduction: 'scoringReduction', robust_best_instance: 'robustBestInstance', oks_stddev: 'oksStddev',
    track_matching_method: 'trackMatchingMethod', max_tracks: 'maxTracks', post_connect_single_breaks: 'postConnectSingleBreaks',
    tracking_target_instance_count: 'targetInstanceCount', tracking_pre_cull_to_target: 'preCullToTarget',
    tracking_pre_cull_iou_threshold: 'preCullIouThreshold', tracking_clean_instance_count: 'cleanInstanceCount',
    tracking_clean_iou_threshold: 'cleanIouThreshold',
};

group('Every track id matches upstream sleap-nn (synthetic fixture, 6 configs)');
{
    const ref = JSON.parse(fs.readFileSync(path.join(HERE, 'fixtures', 'sleap-tracker', 'reference.json'), 'utf8'));
    const frames = ref.frames.map((dets, f) => ({
        frameIdx: f,
        dets: dets.map(d => ({ points: Float64Array.from(d.p, v => v == null ? NaN : v), score: d.s })),
    }));
    const nDets = frames.reduce((n, fr) => n + fr.dets.length, 0);
    ok(nDets > 3000 && frames.some(fr => !fr.dets.length), `fixture has ${nDets} detections and empty frames`);
    for (const [name, c] of Object.entries(ref.configs)) {
        const cfg = {};
        for (const [k, v] of Object.entries(c.kwargs)) { ok(k in KW, `${name}: knows sleap-nn's ${k}`); cfg[KW[k]] = v; }
        const out = ST.runSleapTracker(frames, cfg);
        let same = 0, i = 0, first = -1;
        out.forEach((ids, f) => ids.forEach(t => {
            const js = t == null ? -1 : t;
            if (js === c.tracks[i]) same++; else if (first < 0) first = f;
            i++;
        }));
        eq(same, c.tracks.length, `${name}: identical track ids (first difference at frame ${first})`);
    }
    // the fixture really exercises what it claims to
    const lucid = ref.configs.known_count_lucid.tracks, many = ref.configs.max_reduction_window1.tracks;
    eq(new Set(lucid.filter(t => t >= 0)).size, 4, 'known count: tracks capped at the animal count');
    ok(lucid.includes(-1), 'known count: detections over the cap are dropped');
    ok(new Set(many).size > 50, `window 1, no cap: many short tracks (${new Set(many).size})`);
    ok(ref.configs.bboxes_iou_culled.tracks.some(t => t < 0), 'the culling config drops detections');
    ok(ref.configs.greedy_centroids.tracks.length === nDets, 'every detection is in every config\'s answer');
}

group('linearSumAssignment is SciPy\'s: optimal, and SciPy\'s choice among ties');
{
    let seed = 7;
    const rnd = () => (seed = (seed * 1103515245 + 12345) % 2147483648) / 2147483648;
    const brute = (C, nr, nc) => {   // min over injective row->col maps (nr <= nc) or col->row (nr > nc)
        let best = Infinity;
        const k = Math.min(nr, nc), rows = nr <= nc;
        const rec = (i, used, s) => {
            if (i === k) { best = Math.min(best, s); return; }
            for (let j = 0; j < (rows ? nc : nr); j++) if (!used[j]) {
                used[j] = 1; rec(i + 1, used, s + (rows ? C[i * nc + j] : C[j * nc + i])); used[j] = 0;
            }
        };
        rec(0, new Uint8Array(rows ? nc : nr), 0);
        return best;
    };
    let optimal = 0, total = 0;
    for (let t = 0; t < 300; t++) {
        const nr = 1 + Math.floor(rnd() * 5), nc = 1 + Math.floor(rnd() * 5);
        const C = Float64Array.from({ length: nr * nc }, () => rnd() < 0.3 ? 0 : Math.round(rnd() * 20) / 4);   // many ties
        const r = ST.linearSumAssignment(C, nr, nc);
        const cost = r.rows.reduce((s, row, i) => s + C[row * nc + r.cols[i]], 0);
        total++; if (Math.abs(cost - brute(C, nr, nc)) < 1e-12 && r.rows.length === Math.min(nr, nc)) optimal++;
        ok(r.rows.every((x, i) => i === 0 || x > r.rows[i - 1]), `rows come back ascending (${nr}x${nc})`);
    }
    eq(optimal, total, 'optimal on 300 random matrices with ties');
    // scipy.optimize.linear_sum_assignment answers (SciPy 1.17)
    const same = (r, rows, cols, m) => eq(JSON.stringify([r.rows, r.cols]), JSON.stringify([rows, cols]), m);
    same(ST.linearSumAssignment(new Float64Array(9), 3, 3), [0, 1, 2], [0, 1, 2], 'constant 3x3 -> identity (SciPy #11602)');
    same(ST.linearSumAssignment(new Float64Array(6), 2, 3), [0, 1], [0, 1], 'constant 2x3 -> first columns');
    same(ST.linearSumAssignment(new Float64Array(6), 3, 2), [0, 1], [0, 1], 'constant 3x2 (transposed) -> first rows');
    same(ST.linearSumAssignment(Float64Array.of(0, 0, 1, 1, 0, 0), 3, 2), [0, 2], [0, 1], 'tall tie: rows 0 and 2');
    same(ST.linearSumAssignment(Float64Array.of(-0.9, -0.2, -0.3, -0.8, 0, 0), 3, 2), [0, 1], [0, 1], 'tall: an all-zero row is left out');
}

group('numpyArgsort is np.argsort on arm64 / non-AVX-512 x86 (greedy matching and NMS read ties from it)');
{
    const CASES = [   // [values, np.argsort(values)] from numpy 2.4.4, aarch64 — n = 17 is the first size that partitions
        [[3.0, Infinity, 0.0, 0.0, 0.0], [2, 3, 4, 0, 1]],
        [[3.0, 2.0, 2.0, 0.0, 2.0, 3.0, 3.0, Infinity, 1.0, 1.0, Infinity, 2.0, 2.0, 3.0, 1.0, 3.0, 0.0], [16, 3, 14, 9, 8, 2, 11, 12, 1, 4, 5, 6, 15, 13, 0, 7, 10]],
        [[0.0, 1.0, 2.0, 2.0, 1.0, 1.0, 0.0, 2.0, 3.0, 0.0, Infinity, 0.0, Infinity, 2.0, 0.0, 3.0, Infinity, 2.0], [0, 14, 6, 11, 9, 1, 4, 5, 13, 17, 7, 3, 2, 15, 8, 10, 12, 16]],
        [[3.0, 1.0, 3.0, 2.0, 2.0, Infinity, 1.0, 1.0, 2.0, 0.0, 2.0, 2.0, 0.0, 0.0, 0.0, 2.0, 2.0, 1.0, 3.0, 1.0], [9, 14, 13, 12, 17, 7, 19, 1, 6, 8, 10, 11, 4, 3, 15, 16, 18, 2, 0, 5]],
        [[Infinity, 2.0, NaN, 3.0, 3.0, 0.0, 3.0, 1.0, 3.0, 2.0, 0.0, 3.0, 3.0, 3.0, 0.0, 0.0, 2.0, 2.0, 0.0, Infinity, 0.0, 0.0, 3.0, 2.0, 0.0, NaN, 3.0, 3.0, 3.0, 3.0, 1.0, 2.0, 1.0], [24, 21, 5, 20, 18, 10, 15, 14, 32, 30, 7, 23, 17, 31, 16, 1, 9, 12, 29, 28, 27, 26, 13, 3, 4, 6, 8, 11, 22, 19, 0, 2, 25]],
    ];
    for (const [v, want] of CASES) eq(JSON.stringify(Array.from(ST.numpyArgsort(v))), JSON.stringify(want), `argsort of ${v.length} values with ties`);
}

group('pySetOrder is CPython 3.11\'s set iteration order (fixed_window\'s columns)');
{
    const CASES = [   // [insertion order, list(set) in CPython 3.11.5]
        [[0, 1, 2], [0, 1, 2]],
        [[3, 150, 9], [9, 3, 150]],
        [[8, 16, 0, 24], [8, 16, 0, 24]],
        [[5, 13, 21, 29, 37, 45, 53], [37, 5, 13, 45, 21, 53, 29]],
        [[100, 200, 300, 400, 500, 600, 700, 800, 900, 1000, 1100, 1200, 1300, 1400, 1500, 1600, 1700, 1800, 1900, 2000],
         [900, 1800, 400, 1300, 800, 1700, 300, 1200, 700, 1600, 200, 1100, 2000, 600, 1500, 100, 1000, 1900, 500, 1400]],
        [[251, 7, 64, 3, 128, 250, 249, 1, 2], [64, 128, 1, 3, 2, 7, 249, 250, 251]],
        [[33, 1, 65, 97, 129, 161, 193, 225, 257], [65, 33, 129, 1, 97, 161, 193, 225, 257]],
    ];
    for (const [ins, want] of CASES) eq(JSON.stringify(ST.pySetOrder(ins)), JSON.stringify(want), `set(${JSON.stringify(ins).slice(0, 40)})`);
    eq(JSON.stringify(ST.pySetOrder([4, 4, 1, 4])), '[1,4]', 'duplicates kept once');
}

group('OKS, culling and connect-single-breaks pieces');
{
    const a = Float64Array.of(0, 0, 10, 0, 10, 10, NaN, NaN);
    eq(ST.computeOks(a, a, 0.025), 1, 'a pose against itself: OKS 1');
    const far = a.map(v => v + 1000);
    eq(ST.computeOks(a, far, 0.025), 0, 'far apart: OKS underflows to exactly 0 (the tie the solver must break like SciPy)');
    ok(Number.isNaN(ST.computeOks(Float64Array.of(NaN, NaN), Float64Array.of(1, 1), 0.025)), 'no visible gt node: NaN, as numpy (0/0)');
    eq(ST.countValidPoints(a), 3, 'countValidPoints counts nodes with both coordinates');
    const dets = [{ points: Float64Array.of(0, 0, 10, 10), score: 0.9 }, { points: Float64Array.of(1, 1, 11, 11), score: 0.5 },
                  { points: Float64Array.of(50, 50, 60, 60), score: 0.2 }];
    eq(JSON.stringify(ST.instancesOverCount(dets, 2, 0)), '[2]', 'cull by score: the lowest goes');
    eq(JSON.stringify(ST.instancesOverCount(dets, 2, 0.5)), '[1]', 'cull by IOU first: the overlapping lower-score pose goes');
    const fr = [{ ids: [0, 1] }, { ids: [0, 2] }, { ids: [0, 2] }, { ids: [0, 1, 2] }];
    ST.connectSingleBreaks(fr);
    eq(JSON.stringify(fr.map(x => x.ids)), '[[0,1],[0,1],[0,1],[0,1,2]]', 'one track lost + one new on a frame: the new one takes the lost id from then on');
}

group('Config handling follows sleap-nn');
{
    const t = new ST.SleapTracker({ maxTracks: 3 });
    eq(t.cfg.candidatesMethod, 'local_queues', 'a track cap under fixed_window switches to local_queues (from_config)');
    eq(t.cfg.oksStddev, 0.025, 'oks_stddev defaults to 0.025');
    let threw = false;
    try { ST.runSleapTracker([], { postConnectSingleBreaks: true }); } catch (e) { threw = /target_instance_count/.test(e.message); }
    ok(threw, 'connect-single-breaks without a target count is refused, as by run_tracker');
    const user = new ST.SleapTracker({});
    const ids = user.track([{ points: Float64Array.of(0, 0), score: 1 }, { points: Float64Array.of(5, 5), score: NaN, isUser: true }], 0);
    ok(ids[0] === undefined && ids[1] === 0, 'a frame with a user instance: only it is tracked, the prediction is left alone');
}

console.log(`\n${failed === 0 ? '✓ PASS' : '✗ FAIL'} — ${passed} passed, ${failed} failed`);
if (failed > 0) { console.error('\nFailures:\n - ' + failures.join('\n - ')); process.exit(1); }
